static const double pi=3.141592653589793;
Image cameraPixels(const Image& raw,const Settings& settings){return settings.infrared?grayscale(raw):raw;}
double eyeRatio(const std::vector<Point>& points,const int k[6]){if(points.size()<468)return 0;double width=distance(points[k[0]],points[k[3]]);return width>1?(distance(points[k[1]],points[k[5]])+distance(points[k[2]],points[k[4]]))/(2*width):0;}
static double overlap(Rect a,Rect b){return intersection(a,b).area()/std::max(1.,double(a.area()+b.area()-intersection(a,b).area()));}
static bool eyeObservable(const Image& image,const std::vector<Point>& p,const int k[6]){double width=distance(p[k[0]],p[k[3]]);if(width<12)return false;Point centre((p[k[0]].x+p[k[3]].x)*.5,(p[k[0]].y+p[k[3]].y)*.5);Rect patch((int)(centre.x-width*.65),(int)(centre.y-width*.35),(int)(width*1.3),(int)(width*.7));if(intersection(patch,{0,0,image.width,image.height}).area()!=patch.area()||patch.area()<50)return false;Quality q=quality(image,patch);return q.mean>18&&q.mean<238&&q.sd>=6&&q.sharpness>=3&&!(q.mean<55&&q.dark>.65);}
