 if(faces.empty()||faces[0].score<.65){f.reason="No reliable face detected in monitoring ROI";return f;}if(faces.size()!=1){f.reason="Multiple faces in monitoring ROI; select one person with --roi";return f;}auto detected=faces[0];f.face=intersection(detected.box,{0,0,image.width,image.height});f.faceConfidence=detected.score;f.facePresent=true;if(f.face.width<80||f.face.height<80){f.reason="Face too small; move camera closer";return f;}f.identityChanged=previousFace_.area()>0&&(overlap(previousFace_,f.face)<.15||timestamp-previousFaceTime_>2);previousFace_=f.face;previousFaceTime_=timestamp;Quality q=quality(image,f.face);if(q.mean<12||q.mean>242||q.sd<10||q.sharpness<12||q.clipped>.35){f.reason="Insufficient raw face detail: dark, glare, saturation or blur";return f;}
