 auto mesh=mesh_.forward(inputTensor(crop,192,1./255,0));const Tensor *landmarks=NULL,*presence=NULL;for(const auto& t:mesh){if(t.values.size()==468*3)landmarks=&t;else if(t.values.size()==1)presence=&t;}if(!landmarks||!presence)throw std::runtime_error("Unexpected landmark layout");f.meshConfidence=1./(1+std::exp(-std::max(-80.,std::min(80.,double(presence->values[0])))));if(f.meshConfidence<.9){f.reason="Unreliable face landmarks";return f;}for(int i=0;i<468;++i){double x=landmarks->values[i*3],y=landmarks->values[i*3+1];if(!std::isfinite(x)||!std::isfinite(y))throw std::runtime_error("Nonfinite landmark output");f.landmarks.push_back(toSource(x,y));}
 const int left[6]={33,160,158,133,153,144},right[6]={362,385,387,263,373,380};f.leftEar=eyeRatio(f.landmarks,left);f.rightEar=eyeRatio(f.landmarks,right);double mw=distance(f.landmarks[78],f.landmarks[308]);f.mar=mw>1?distance(f.landmarks[13],f.landmarks[14])/mw:0;f.poseReliable=estimatePose(f.landmarks,image.width,image.height,f.face,f.pitch,f.yaw,f.roll);auto inside=[&](Point p){return p.x>=0&&p.y>=0&&p.x<image.width&&p.y<image.height;};f.mouthVisible=f.poseReliable&&inside(f.landmarks[13])&&inside(f.landmarks[14]);bool eyeQuality=eyeObservable(image,f.landmarks,left)&&eyeObservable(image,f.landmarks,right);f.eyesVisible=eyeQuality&&settings_.eyewear!="opaque"&&f.poseReliable&&std::abs(f.yaw)<=settings_.yawLimit&&std::abs(f.pitch)<=settings_.pitchLimit&&std::abs(f.roll)<=45;f.reason=!f.poseReliable?"Head pose/landmark geometry unreliable":settings_.eyewear=="opaque"?"Opaque-eyewear mode: eye state cannot be verified":std::abs(f.yaw)>settings_.yawLimit||std::abs(f.pitch)>settings_.pitchLimit||std::abs(f.roll)>45?"Face angle exceeds supported observation limits":!eyeQuality?"Eyes obscured, too small, low contrast or glare":"Usable face/eye observation";return f;
